module fifo_occ_flags (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_wr,
    input  wire       i_rd,
    input  wire [7:0] i_data,
    output wire [7:0] o_data,
    output wire       o_full,
    output wire       o_empty
);
    // depth-8 FIFO: 4-bit pointers (extra MSB for wrap), separate occupancy count
    reg [3:0] wptr;
    reg [3:0] rptr;
    reg [3:0] count;
    reg [7:0] mem [0:7];
    reg [7:0] dout;

    integer i;
    initial begin
        wptr  = 4'd0;
        rptr  = 4'd0;
        count = 4'd0;
        dout  = 8'd0;
        for (i = 0; i < 8; i = i + 1)
            mem[i] = 8'd0;
    end

    // full is derived from the occupancy counter,
    // empty is derived from the pointers
    assign o_full  = (count == 4'd8);
    assign o_empty = (wptr == rptr);

    wire do_wr = i_wr && !o_full;
    wire do_rd = i_rd && !o_empty;

    assign o_data = dout;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 4'd0;
            rptr  <= 4'd0;
            count <= 4'd0;
            dout  <= 8'd0;
        end else begin
            if (do_wr) begin
                mem[wptr[2:0]] <= i_data;
                wptr <= wptr + 4'd1;
            end
            if (do_rd) begin
                dout <= mem[rptr[2:0]];
                rptr <= rptr + 4'd1;
            end
            if (do_wr && !do_rd)
                count <= count + 4'd1;
            else if (!do_wr && do_rd)
                count <= count - 4'd1;
        end
    end

    // P: the FIFO is never reported full and empty at the same time
    always @(posedge clk)
        assert (!(o_full && o_empty));
endmodule

