module fifo_checker (
    input wire i_clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_wr,
    input wire i_rd,
    output wire full,
    output wire empty
);
    parameter DEPTH = 8;
    reg [3:0] wptr, rptr, occ;
    initial wptr = 4'd0;
    initial rptr = 4'd0;
    initial occ = 4'd0;

    always @(posedge i_clk)
        if (i_reset) begin
            wptr <= 4'd0;
            rptr <= 4'd0;
            occ <= 4'd0;
        end else if (i_ce) begin
            case ({i_wr, i_rd})
                2'b00: ;
                2'b01: if (occ != 4'd0) begin
                        rptr <= rptr + 4'd1;
                        occ <= occ - 4'd1;
                     end
                2'b10: if (occ != 4'd8) begin
                        wptr <= wptr + 4'd1;
                        occ <= occ + 4'd1;
                     end
                2'b11: if (occ != 4'd0 && occ != 4'd8) begin
                        rptr <= rptr + 4'd1;
                        wptr <= wptr + 4'd1;
                     end
            endcase
        end

    assign full = (occ == 4'd8);
    assign empty = (occ == 4'd0);

    always @(posedge i_clk)
        if (i_ce)
            assert ((wptr - rptr) == occ);

    always @(posedge i_clk)
        if (i_ce)
            assert (occ <= 4'd8);

    always @(posedge i_clk)
        if (i_ce)
            assert (!(occ == 4'd8) || (wptr - rptr) == 4'd8);

    always @(posedge i_clk)
        if (i_ce)
            assert (!(occ == 4'd0) || (wptr == rptr));

    always @(posedge i_clk)
        if (i_ce)
            assert (occ != 4'd1 || ((wptr - rptr) == 4'd1));

    always @(posedge i_clk)
        if (i_ce)
            assert (occ != 4'd2 || ((wptr - rptr) == 4'd2));

    always @(posedge i_clk)
