    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            expired  <= 1'b0;
            hard_rst <= 1'b0;
            if (kick) begin
                cnt <= 4'd0;
            end else if (timeout) begin
                cnt     <= 4'd0;
                expired <= 1'b1;
                if (strikes == 3'd2) begin
                    strikes  <= 3'd0;
                    hard_rst <= 1'b1;
                end else begin
                    strikes <= strikes + 3'd1;
                end
            end else begin
                cnt <= cnt + 4'd1;
            end
        end
    end

    // P: whenever the timeout notification rises, the strike budget of 2 has
    //    never been exceeded (3-bit register could hold up to 7).
    always @(posedge clk)
        if (pv && $rose(expired))
            assert (strikes <= 3'd2);
