module txn_scoreboard (
    input wire clk,
    input wire ce,
    input wire issue,
    input wire retire_req,
    output reg [2:0] outstanding,
    output reg       armed
);
    // issued/retired transaction counters (scoreboard)
    reg [3:0] issued;
    reg [3:0] retired;
    // bounded-response countdown for the oldest outstanding transaction
    reg [2:0] ttl;

    localparam [2:0] WINDOW = 3'd4;
    localparam [2:0] RELOAD = 3'd5;

    initial begin
        issued      = 4'd0;
        retired     = 4'd0;
        outstanding = 3'd0;
        ttl         = RELOAD;
        armed       = 1'b0;
    end

    // the completion engine is forced to retire when the countdown hits one
    wire force_retire = (outstanding != 3'd0) && (ttl == 3'd1);
    wire do_retire    = (retire_req && (outstanding != 3'd0)) || force_retire;
    wire do_issue     = issue && (outstanding < WINDOW);

    wire [2:0] nxt_out = outstanding
                       + (do_issue  ? 3'd1 : 3'd0)
                       - (do_retire ? 3'd1 : 3'd0);

    always @(posedge clk) begin
        if (ce) begin
            if (do_issue) begin
                issued <= issued + 4'd1;
                armed  <= 1'b1;          // sticky: never cleared
            end
            if (do_retire)
                retired <= retired + 4'd1;

            outstanding <= nxt_out;

            if (do_retire)
                ttl <= RELOAD;           // a completion restarts the window
            else if (nxt_out != 3'd0)
                ttl <= ttl - 3'd1;       // tick down while work is pending
            else
                ttl <= RELOAD;           // idle scoreboard parks at full
        end
    end

    // P: once the scoreboard has ever accepted a transaction, the completion
    // countdown never expires while transactions are still outstanding.
    always @(posedge clk)
        if (armed && (outstanding != 3'd0))
            assert (ttl != 3'd0);
endmodule

