    input  wire       rst,
    input  wire       issue,          // producer spends a credit (dispatch a signing request)
    input  wire       ret,            // consumer returns a credit (signature delivered)
    output reg  [3:0] credits_avail,  // credits held by the dispatcher
    output reg  [3:0] credits_out,    // credits outstanding in the signing pipeline
    output reg        hit_hw,         // shadow: outstanding count once reached the high-water mark
    output reg        started         // shadow: at least one request was ever issued
);
    localparam [3:0] TOTAL = 4'd8;
    localparam [3:0] HW    = 4'd4;

    initial credits_avail = TOTAL;
    initial credits_out   = 4'd0;
    initial hit_hw        = 1'b0;
    initial started       = 1'b0;

    // idle when issue and ret are both low (or both high): nothing changes
    wire do_issue = issue && !ret && (credits_avail != 4'd0);
    wire do_ret   = ret && !issue && (credits_out   != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            credits_avail <= TOTAL;
            credits_out   <= 4'd0;
            hit_hw        <= 1'b0;
            started       <= 1'b0;
        end else begin
            if (do_issue) begin
                credits_avail <= credits_avail - 4'd1;
                credits_out   <= credits_out   + 4'd1;
                started       <= 1'b1;
                if (credits_out >= (HW - 4'd1))
                    hit_hw <= 1'b1;
            end else if (do_ret) begin
                credits_avail <= credits_avail + 4'd1;
                credits_out   <= credits_out   - 4'd1;
            end
        end
    end

    // Precedence, global scope, two assertions sharing one relation:
    //  - if the dispatcher is down to half its credits, the pipeline must have
    //    reached the high-water mark at some earlier point;
    //  - if the dispatcher no longer holds the full budget, some request must
    //    have been issued earlier.
    always @(posedge clk) begin
        if (credits_avail <= HW)
            assert (hit_hw);
        if (credits_avail != TOTAL)
            assert (started);
    end
endmodule

