module pslice_check (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] data_in,
    output wire [7:0] data_out,
    output wire       par_out,
    output wire       val_out,
    output wire [5:0] o_chk_cnt,
    output wire [5:0] o_ok_cnt
);
    // input register slice, protected by a stored parity bit
    reg [7:0] s0_data;
    reg       s0_par;
    reg       s0_val;

    // output register slice, carries the same protection
    reg [7:0] s1_data;
    reg       s1_par;
    reg       s1_val;

    // retirement bookkeeping
    reg [5:0] chk_cnt;
    reg [5:0] ok_cnt;

    initial begin
        s0_data = 8'h00;
        s0_par  = 1'b0;
        s0_val  = 1'b0;
        s1_data = 8'h00;
        s1_par  = 1'b0;
        s1_val  = 1'b0;
        chk_cnt = 6'd0;
        ok_cnt  = 6'd0;
    end

    // parity checker sitting between the two slices
    wire s0_bad = s0_val && (s0_par ^ (^s0_data));

