module pingpong_buffer (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       wr_data_valid,
    input  wire       rd_ready,
    input  wire       start,
    input  wire       stop,
    output wire [2:0] wr_addr,
    output wire [2:0] rd_addr,
    output wire       busy
);
    localparam [2:0] HALF = 3'd4;

    // ping-pong double buffer: writer owns half wr_sel, reader owns half rd_sel
    reg       wr_sel;
    reg       rd_sel;
    reg [2:0] wcnt;      // words written into the write half
    reg [2:0] rcnt;      // words consumed from the read half
    reg       rd_valid;  // read half currently holds a full block
    reg       active;    // streaming session engaged
    reg       pv;        // past-valid

    initial begin
        wr_sel   = 1'b0;
        rd_sel   = 1'b1;
        wcnt     = 3'd0;
        rcnt     = 3'd0;
        rd_valid = 1'b0;
        active   = 1'b0;
        pv       = 1'b0;
    end

    wire do_write = ce && wr_data_valid && (wcnt != HALF);
    wire do_read  = ce && rd_ready && rd_valid && (rcnt != HALF);
    wire swap     = ce && (wcnt == HALF) && !rd_valid;

    assign wr_addr = {wr_sel, wcnt[1:0]};
    assign rd_addr = {rd_sel, rcnt[1:0]};
    assign busy    = active;

    always @(posedge clk) begin
        pv <= 1'b1;
    end

    always @(posedge clk) begin
        if (ce) begin
            if (rst) begin
                wr_sel   <= 1'b0;
                rd_sel   <= 1'b1;
                wcnt     <= 3'd0;
                rcnt     <= 3'd0;
                rd_valid <= 1'b0;
                active   <= 1'b0;
            end else begin
                if (stop)
                    active <= 1'b0;
                else if (start)
                    active <= 1'b1;

                if (swap) begin
                    // both owners move to the opposite half on the same edge
                    wr_sel   <= ~wr_sel;
                    rd_sel   <= ~rd_sel;
                    wcnt     <= 3'd0;
                    rcnt     <= 3'd0;
                    rd_valid <= 1'b1;
                end else begin
                    if (do_write)
                        wcnt <= wcnt + 3'd1;
                    if (do_read) begin
                        rcnt <= rcnt + 3'd1;
                        if ((rcnt + 3'd1) == HALF)
                            rd_valid <= 1'b0;
                    end
                end
            end
        end
    end

    // P: whenever a streaming session engages, the two owners are on opposite halves
    always @(posedge clk) begin
        if (pv && $rose(active))
            assert (wr_sel != rd_sel);
    end
endmodule

