module tmr_alert_window (
    input  wire       clk,
    input  wire       ce,       // global enable: low => all state frozen
    input  wire       load,     // write a new severity into the redundant bank
    input  wire [3:0] sev_in,
    input  wire       q_open,   // Q: escalation opened  (arms the window)
    input  wire       r_close,  // R: escalation closed  (disarms the window)
    output wire [3:0] voted,
    output wire       in_window
);
    // triple-modular-redundant severity register
    reg [3:0] copy_a;
    reg [3:0] copy_b;
    reg [3:0] copy_c;

    // shadow register: severity recorded at the moment the window opened
    reg [3:0] arm_val;
    // window register: set by Q, cleared by R
    reg       armed;

    initial begin
        copy_a  = 4'b0000;
        copy_b  = 4'b0000;
        copy_c  = 4'b0000;
        arm_val = 4'b0000;
        armed   = 1'b0;
    end

    // bitwise majority voter over the three shadow copies
    wire [3:0] vote = (copy_a & copy_b) | (copy_a & copy_c) | (copy_b & copy_c);

    assign voted     = vote;
    assign in_window = armed;

    // the bank is only rewritten while the window is closed and not opening
    wire do_load = ce && load && !armed && !q_open;

    always @(posedge clk) begin
        if (do_load) begin
            copy_a <= sev_in;
            copy_b <= sev_in;
            copy_c <= sev_in;
        end
        if (ce) begin
            if (r_close) begin
                armed <= 1'b0;
            end else if (q_open) begin
                armed   <= 1'b1;
                arm_val <= copy_a;   // capture from the primary copy
            end
        end
    end

    // P: inside the escalation window, what is voted now must be exactly the
    // severity that was recorded earlier, when the window was opened.
    always @(*)
        if (armed)
            assert (vote == arm_val);

endmodule

