// Tracks in-flight requests in an 8-deep shift register with a separate
// population count.  A parity/CDC error input permanently degrades the
// tracker: once `err` has been seen, the count stops being maintained
// while the shift register keeps shifting.  The occupancy relations are
// therefore only claimed before that first error.
module inflight_tracker (
    input  wire       clk,
    input  wire       step,      // idle condition: step low freezes all state
    input  wire       req,       // new request enters the pipeline this step
    input  wire       err,       // degradation event (clears the arming reg)
    output reg  [7:0] inflight,  // one bit per pipeline stage, MSB retires
    output reg  [3:0] count,     // number of set bits in `inflight`
    output reg        live       // arming register: high before any err
);

    initial inflight = 8'd0;
    initial count    = 4'd0;
    initial live     = 1'b1;

    wire retire = inflight[7];

    always @(posedge clk) begin
        if (err)
            live <= 1'b0;

        if (step) begin
            inflight <= {inflight[6:0], req};
            // the bookkeeping count is only kept faithful while undegraded
            if (live && !err)
                count <= count + (req ? 4'd1 : 4'd0) - (retire ? 4'd1 : 4'd0);
        end
    end

    // Two universality properties, both scoped to "before the first err".
    always @(posedge clk) begin
        if (live && count == 4'd0)
            assert (inflight == 8'h00);
        if (live && count == 4'd8)
            assert (inflight == 8'hFF);
    end

endmodule

