        if (i_rst) begin
            cnt     <= 4'd0;
            full_f  <= 1'b0;
            empty_f <= 1'b1;
        end else if (i_ce) begin
            if (i_clear) begin
                cnt     <= 4'd0;
                full_f  <= 1'b0;
                empty_f <= 1'b1;
