    reg       expired;
    reg       armed;   // sticky: set the first time the dog is ever kicked

    initial wdt     = 5'd0;
    initial expired = 1'b0;
    initial armed   = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            wdt     <= 5'd0;
            expired <= 1'b0;
            armed   <= 1'b0;
        end else if (ce) begin
            if (kick) begin
                wdt     <= 5'd0;
                expired <= 1'b0;
                armed   <= 1'b1;
            end else if (!expired) begin
                wdt <= wdt + 5'd1;
                if ((wdt + 5'd1) == LIMIT)
                    expired <= 1'b1;
            end
        end
    end

