    reg [4:0]  beats_done;
    reg [4:0]  burst_len;
    reg [11:0] addr;
    reg [11:0] base;

    initial begin
        o_busy     = 1'b0;
        beats_left = 5'd0;
        beats_done = 5'd0;
        burst_len  = 5'd0;
        addr       = 12'd0;
        base       = 12'd0;
    end

