    wire [11:0] end_addr = base + ({7'd0, burst_len} << 2);

    always @(posedge clk) begin
        if (rst) begin
            o_busy     <= 1'b0;
            beats_left <= 5'd0;
            beats_done <= 5'd0;
            burst_len  <= 5'd0;
            addr       <= 12'd0;
            base       <= 12'd0;
