    assign full  = (count == 4'd8);
    assign empty = (count == 4'd0);

    wire do_push = push && !full;
    wire do_pop  = pop  && !empty;

    wire [3:0] nxt_count = count + (do_push ? 4'd1 : 4'd0) - (do_pop ? 4'd1 : 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 3'd0;
            rptr  <= 3'd0;
            count <= 4'd0;
            armed <= 1'b0;
            rdata <= 8'h00;
        end else begin
            if (do_push) begin
                mem[wptr] <= wdata;
                wptr      <= wptr + 3'd1;
            end
            if (do_pop) begin
                rdata <= mem[rptr];
                rptr  <= rptr + 3'd1;
            end
            count <= nxt_count;
