                dn   <= dn - 5'd1;
               if (pend == 3'd3) begin
                   up   <= up + 5'd4;   // fold a full batch into the total
                   pend <= 3'd0;
               end else begin
                   pend <= pend + 3'd1;
               end
               mark <= mark | (taken == 5'd9);
            end
        end
    end

