    always @(posedge clk) begin
        if (rst) begin
            pipe     <= 4'b0000;
            inflight <= 3'd0;
req_hist     <= 4'b0000;
o_issue_hist <= 4'b0000;
ce_cnt       <= 4'b0000;
o_act_cnt    <= 4'b0000;
