                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 : 4'b0000;
            2'd2: gnt_c = req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 :
