    wire accept = i_ce && i_launch && armed;
   // the issue stage takes the express lane only when the array is empty
   wire xpr_take = ln_stage && (pipe == {STAGES{1'b0}});
   wire retire = i_ce && (pipe[STAGES-1] || xpr);

