 // into the source pointer, n_retire logs advances absorbed by the chain-A
 // shadow stage.  Both are plain free-running event counters that wrap at
 // four bits; only their difference is meaningful.
 reg  [3:0] n_issue;
 reg  [3:0] n_retire;

    initial begin
        wbin       = 4'd0;
        sync1      = 4'd0;
        sync2      = 4'd0;
        b1         = 4'd0;
        b2         = 4'd0;
       s1b        = 4'd0;
       s2b        = 4'd0;
       b1b        = 4'd0;
       b2b        = 4'd0;
       phase      = 1'b0;
      wrap_mask  = 4'd1;
     n_issue    = 4'd0;
     n_retire   = 4'd0;
        armed      = 1'b0;
        last_delta = 3'd0;
    end

