           sync1     <= 4'd0;
           sync2     <= 4'd0;
           b1        <= 4'd0;
           b2        <= 4'd0;
           s1b       <= 4'd0;
           s2b       <= 4'd0;
           b1b       <= 4'd0;
           b2b       <= 4'd0;
          n_issue   <= 4'd0;
          n_retire  <= 4'd0;
