    input  wire clk,
    input  wire i_ce,      // global enable: low => the engine idles
    input  wire i_arm,
    input  wire i_start,
    input  wire i_done,
    input  wire i_flush,
    output wire o_fin_seen,
output wire o_busy,
output reg [3:0] o_evt_cnt
