    localparam [3:0] TOTAL = 4'd3;
   localparam [3:0] CR_MIN = 4'd1;

    // ---- credit counter: credits held + credits in each stage == TOTAL ----
    reg [3:0] free_cr;    // credits held by the producer
    reg [3:0] armed_cr;   // credits spent on ARM, awaiting START
    reg [3:0] busy_cr;    // credits outstanding at the consumer

   // ---- adaptive credit budget: the pool in circulation is trimmed when a
   //      flush has to tear down live traffic, and healed one credit at a
   //      time while the whole engine is quiescent ----
   reg [3:0] cr_lim;     // credits currently in circulation

