                       st_s  <= S_IDENT;
                       len_s <= 3'd1;
                    end else if (cls == 2'd2) begin
                       st_s  <= S_NUM;
                       len_s <= 3'd1;
                    end else if (cls == 2'd3) begin
                       st_s  <= S_STR;
                       len_s <= 3'd0;
