);
    // binary-encoded loader FSM: IDLE/OPEN/HEADER/ROWS/DONE
    // encodings 101, 110, 111 are never entered by construction
    localparam [2:0] S_IDLE   = 3'b000,
                     S_OPEN   = 3'b001,
                     S_HEADER = 3'b010,
                     S_ROWS   = 3'b011,
                     S_DONE   = 3'b100;

    reg [2:0] st;
    reg       loading;
    reg       ready;
   reg       fin_pend;
    reg [3:0] rows;

    initial st      = S_IDLE;
    initial loading = 1'b0;
    initial ready   = 1'b0;
   initial fin_pend = 1'b0;
    initial rows    = 4'd0;
initial o_ce_beats = 4'd0;

    always @(posedge clk) begin
        if (i_reset) begin
            st      <= S_IDLE;
            loading <= 1'b0;
            ready   <= 1'b0;
           fin_pend <= 1'b0;
            rows    <= 4'd0;
o_ce_beats <= 4'd0;
        end else if (i_ce) begin
o_ce_beats <= o_ce_beats + {3'd0, i_start};
           // completion is committed one beat after the FSM posts it
           ready <= fin_pend;
            case (st)
                S_IDLE: begin
                    if (i_start) begin
                        st      <= S_OPEN;
                        loading <= 1'b1;
                    end else begin
                        st      <= S_IDLE;
                        loading <= 1'b0;
                    end
                end
                S_OPEN: begin
                    st      <= S_HEADER;
                    loading <= 1'b1;
                    rows    <= 4'd0;
                end
                S_HEADER: begin
                    st      <= S_ROWS;
                    loading <= 1'b1;
                end
                S_ROWS: begin
                    if (i_last_row) begin
                        st      <= S_DONE;
                        loading <= 1'b0;
                       fin_pend <= 1'b1;
                    end else begin
                        st      <= S_ROWS;
                        loading <= 1'b1;
                        rows    <= rows + 4'd1;
                    end
                end
                S_DONE: begin
                    st      <= S_IDLE;
                    loading <= 1'b0;
