module lock_arbiter_occ (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire [3:0] i_req,
    output wire [3:0] o_grant,
    output wire       o_busy
);
    // fixed-priority arbiter with a lock bit that freezes the winner
    reg [3:0] grant;
    reg       lock;
    // shadow occupancy counter: how many grants are currently outstanding
    reg [2:0] occ;
    // lock-hold timer: beats the current owner has held the bus
    reg [2:0] hold_cnt;

    initial grant = 4'b0000;
    initial lock  = 1'b0;
    initial occ   = 3'd0;
    initial hold_cnt = 3'd0;

    wire        busy    = (grant != 4'b0000);
    wire        any_req = (i_req != 4'b0000);

    // fixed priority: channel 0 highest
    wire [3:0] pri_grant = i_req[0] ? 4'b0001 :
                           i_req[1] ? 4'b0010 :
                           i_req[2] ? 4'b0100 :
                           i_req[3] ? 4'b1000 : 4'b0000;
    // anti-starvation: the lock expires after 5 held beats so lower channels can win
    wire lock_expired = (hold_cnt >= 3'd5);

    // while locked, the current winner keeps the bus as long as it still asks
    wire holding = busy && lock && !lock_expired && ((grant & i_req) != 4'b0000);

    always @(posedge i_clk) begin
        if (i_rst) begin
            grant <= 4'b0000;
            lock  <= 1'b0;
            occ   <= 3'd0;
            hold_cnt <= 3'd0;
        end else if (i_ce) begin
            if (busy) begin
                if (!holding) begin
                    // winner released: drop the grant and free the slot
                    grant <= 4'b0000;
                    lock  <= 1'b0;
                    occ   <= occ - 3'd1;
                    hold_cnt <= 3'd0;
                end
                else begin
                    // still holding: age the lock
                    hold_cnt <= hold_cnt + 3'd1;
                end
            end else if (any_req) begin
                // bus free: award it and lock it
                grant <= pri_grant;
                lock  <= 1'b1;
                occ   <= occ + 3'd1;
                hold_cnt <= 3'd0;
            end
        end
    end

    assign o_grant = grant;
    assign o_busy  = busy;

    // at most one grant may be outstanding at any time
    always @(*)
        assert (occ <= 3'd1);

    // the hold timer only ages while a grant is outstanding
    always @(posedge i_clk)
        assert ((hold_cnt == 3'd0) || (occ == 3'd1));
endmodule

