         drop_cnt    <= 4'd0;
post_cnt    <= 4'd0;
rtr_cnt     <= 4'd0;
mw_opn      <= 4'd0;
mw_cls      <= 4'd0;
lock_arm    <= 1'b0;
       end else if (ce && !park) begin
