                    out_valid <= 1'b1;
                    out_code  <= in_code;
                end else begin
                    out_valid <= 1'b0;
                end
            end

            // skid buffer: only loaded while the stage is stalled
            if (skid_valid) begin
               if (out_room) begin
                   // head drains into the output register; refill it from
                   // the tail slot, or straight from the producer
                   if (skid2_valid) begin
                       skid_valid <= 1'b1;
                       skid_code  <= skid2_code;
                   end else if (in_valid && in_ready) begin
                       skid_valid <= 1'b1;
                       skid_code  <= in_code;
                   end else begin
                       skid_valid <= 1'b0;
                   end
               end
           end else if (in_valid && in_ready && !out_room) begin
                skid_valid <= 1'b1;
                skid_code  <= in_code;
            end

           // tail slot: only fills behind a full head slot while the
           // output register is blocked, and always shifts down on a drain
           if (skid2_valid) begin
               if (out_room)
                   skid2_valid <= 1'b0;
           end else if (in_valid && in_ready && skid_valid && !out_room) begin
               skid2_valid <= 1'b1;
               skid2_code  <= in_code;
           end

            // producer advances on every accepted word
            if (in_valid && in_ready)
                src_phase <= (src_phase == 2'd2) ? 2'd0 : src_phase + 2'd1;

