// Simple token-lexer FSM: binary-encoded states 0..4, encodings 5..7 unused.
module lex_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [1:0] cls,     // 0=escape/backslash, 1=alpha, 2=digit, 3=quote
    output reg  [2:0] st,
    output reg  [2:0] len
);
    localparam [2:0] S_IDLE  = 3'd0;
    localparam [2:0] S_IDENT = 3'd1;
    localparam [2:0] S_NUM   = 3'd2;
    localparam [2:0] S_STR   = 3'd3;
    localparam [2:0] S_ESC   = 3'd4;
    // An escape can now be taken from top level or from inside an identifier,
    // so S_ESC alone no longer says which token is being built: the state code
    // to resume with is held here while st == S_ESC.
    reg [2:0] esc_ret;
   // Second lexer channel. The two character streams are interleaved on cls
   // and take turns owning the single decode/commit datapath below. Channel B
   // measures records rather than tokens, so its length is carried across a
   // token boundary instead of being cleared.
   reg [2:0] st_b;
   reg [2:0] len_b;
   reg [2:0] esc_b;
   reg       own;   // 0 = channel A owns the shared datapath, 1 = channel B
   // Decode and commit are now separate cycles: the next-state decode and the
   // length adder no longer share one combinational path to the outputs. A
   // character is absorbed into the staging pair in one cycle and the pair is
   // driven onto st/len in the next.
   reg [2:0] st_s;
   reg [2:0] len_s;
   reg       s_vld;

   wire [2:0] cur_st  = own ? st_b  : st;
   wire [2:0] cur_len = own ? len_b : len;
   wire [2:0] cur_esc = own ? esc_b : esc_ret;
   wire [2:0] len_inc = (cur_len == 3'd7) ? 3'd7 : (cur_len + 3'd1);

    initial st  = S_IDLE;
    initial len = 3'd0;
    initial esc_ret = S_IDLE;
   initial st_s  = S_IDLE;
   initial len_s = 3'd0;
   initial s_vld = 1'b0;
   initial st_b  = S_IDLE;
   initial len_b = 3'd0;
   initial esc_b = S_IDLE;
   initial own   = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            st  <= S_IDLE;
            len <= 3'd0;
            esc_ret <= S_IDLE;
           st_s  <= S_IDLE;
           len_s <= 3'd0;
           s_vld <= 1'b0;
           st_b  <= S_IDLE;
           len_b <= 3'd0;
           esc_b <= S_IDLE;
           own   <= 1'b0;
        end else if (ce) begin
           if (s_vld) begin
              if (own) begin
                  st_b  <= st_s;   // commit cycle: the staged pair goes back
                  len_b <= len_s;  // to whichever channel was decoded
              end else begin
                  st    <= st_s;
                  len   <= len_s;
              end
               s_vld <= 1'b0;
              own   <= ~own;   // round-robin: the other stream gets the next char
