   reg       p1_b;
   reg       p1_take;
   reg       p2_a;
   reg       p2_b;
   reg       p2_take;
   reg       p3_a;
   reg       p3_b;
   reg       p3_take;
   reg       p4_a;
   reg       p4_b;
   reg       p4_take;

    initial used  = 4'd0;
    initial avail = CAP;
   initial out_a = 4'd0;
   initial out_b = 4'd0;
  initial rsv_a = 2'd0;
   initial turn  = 1'b0;
   initial gnt_a = 1'b0;
   initial gnt_b = 1'b0;
   initial gnt_take = 1'b0;
   initial p1_a = 1'b0;
   initial p1_b = 1'b0;
   initial p1_take = 1'b0;
   initial p2_a = 1'b0;
   initial p2_b = 1'b0;
   initial p2_take = 1'b0;
   initial p3_a = 1'b0;
   initial p3_b = 1'b0;
   initial p3_take = 1'b0;
   initial p4_a = 1'b0;
   initial p4_b = 1'b0;
   initial p4_take = 1'b0;

  wire       lane_nz  = turn ? (out_b != 4'd0) : (out_a != 4'd0 || rsv_a != 2'd0);
   wire       arb_idle = !gnt_a && !gnt_b && !p1_a && !p1_b &&
                         !p2_a && !p2_b && !p3_a && !p3_b && !p4_a && !p4_b;

