// ledger chases the hand-over ledger, so the port comes back on the next
// advance after it was taken
wire       lend      = !port_out && kick;
wire       back      = (n_lend != n_back);
wire [3:0] n_lend_nx = n_lend + (lend ? 4'd1 : 4'd0);
wire [3:0] n_back_nx = n_back + (back ? 4'd1 : 4'd0);
wire       port_nx   = lend || (port_out && !back);
// the commit slot takes the result on the advance the port comes back and
// the commit stage drains it on the advance after that
wire       rb_take   = back;
wire       rb_free   = (n_post != n_pop);
wire       rb_nx     = rb_take || (rb_full && !rb_free);
wire [3:0] n_post_nx = n_post + (rb_take ? 4'd1 : 4'd0);
wire [3:0] n_pop_nx  = n_pop  + (rb_free ? 4'd1 : 4'd0);

