            state <= S_IDLE;
            dec   <= 5'b00001;
           dec_s <= 5'b00001;
            win   <= 1'b0;
           tail  <= 1'b0;
          age   <= 3'd0;
           rjob   <= 1'b0;
           rtimer <= 4'd15;
