module pwm_prio_duty (
    input  wire       clk,
    input  wire       ce,
    input  wire [7:0] req,
    output reg        out_r,
output reg        vld_r,
output reg [3:0] evt_r
);
    // ---------------- PWM state ----------------
    reg [2:0] cnt;        // period counter 0..7
   reg [2:0] per;        // programmed frame length minus one (frame = per+1)
    reg [3:0] duty;       // active duty value 0..8
    reg [3:0] hi_cnt;     // cycles spent high inside the current period
    reg       shadow_nz;  // shadow: the duty programmed for this period was nonzero
    reg       armed;      // scope: high until the first all-zero request load
   reg       duty_ext;   // extra whole cycle granted to this frame by the dither
   reg       dith;       // pending half-step credit carried between frames
reg [3:0] evt_cnt;    // distractor: tally of cycles with an active request

    initial begin
        cnt       = 3'd0;
       per       = 3'd7;   // reset frame is the full eight cycles
        duty      = 4'd4;   // reset duty is nonzero
        hi_cnt    = 4'd0;
        shadow_nz = 1'b1;   // matches reset duty
        armed     = 1'b1;
       duty_ext  = 1'b0;
       dith      = 1'b0;
        out_r     = 1'b0;
        vld_r     = 1'b0;
evt_cnt   = 4'd0;
evt_r     = 4'd0;
    end

    // ---------------- priority encoder over the request vector ----------------
    reg [2:0] idx;
    reg       vld;
    always @(*) begin
        vld = |req;
        if      (req[7]) idx = 3'd7;
        else if (req[6]) idx = 3'd6;
        else if (req[5]) idx = 3'd5;
        else if (req[4]) idx = 3'd4;
        else if (req[3]) idx = 3'd3;
        else if (req[2]) idx = 3'd2;
        else if (req[1]) idx = 3'd1;
        else             idx = 3'd0;
    end

    // requested duty: highest set index + 1, or 0 when no request
    wire [3:0] duty_req = vld ? ({1'b0, idx} + 4'd1) : 4'd0;

   // ---------------- frame-length programming ----------------
   // req[2:0] double as the frame-length code; a requested duty that does not
   // fit in the programmed frame is truncated to 100% of that frame
   wire [2:0] per_nxt  = req[2:0];
   wire [3:0] per_lim  = {1'b0, per_nxt} + 4'd1;
   wire [3:0] duty_nxt = (duty_req > per_lim) ? per_lim : duty_req;
  // ---------------- half-step dither ----------------
  // when several sources request at once the winner earns an extra half cycle
  // of duty for the aggregate load; two half cycles are cashed in as one whole
  // cycle, and the bump is only applied while the duty is below 100% of the
  // frame so that the extra cycle still fits inside the frame
  wire       multi    = vld && ((req & (req - 8'd1)) != 8'd0);
  wire       ext_nxt  = (dith && multi) && (duty_nxt < per_lim);
  wire [3:0] duty_eff = duty + {3'b000, duty_ext};

 // ---------------- frame capacity ----------------
 // 100% of the frame being emitted right now (the programmed per, not the
 // one being loaded); the comparator can never ask for more high time than
 // the frame it belongs to is able to hold
 wire [3:0] cap_now = {1'b0, per} + 4'd1;

    // ---------------- comparator: high exactly while cnt < duty ----------------
wire out  = ({1'b0, cnt} < duty_eff);
   wire wrap = (cnt == per);

    always @(posedge clk) begin
