        if (i_rst) begin
            win   <= 0;
            ones  <= 0;
           adm_q <= 0;
           s1    <= 0;
           s2    <= 0;
           s3    <= 0;
           s4    <= 0;
            armed <= 0;
           gap   <= 0;
n_in  <= 0;
n_out <= 0;
        end else if (i_ce) begin
win   <= { win[W-2:0], s4 };
           ones  <= ones - retiring + (adm_q ? 3'd1 : 3'd0);
adm_q <= s4;
s1    <= allow;
s2    <= s1;
s3    <= s2;
s4    <= s3;
if (allow)
    n_in  <= n_in  + 3'd1;
if (win[W-1])
    n_out <= n_out + 3'd1;
            if (allow)
                armed <= 1'b1;
if (s4)
gap <= cool;
