   // Cooldown consistency: halfway through a cooldown the grant that started it
   // is still resident in the window, so the mirrored occupancy is not empty.
   always @(posedge clk)
       if (pv)
           assert ((gap != 2'd1) || (ones != 3'd0 || adm_q));
