n_cmt      <= 4'd0;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            armed      <= 1'b0;
           ph_ref2    <= 3'd0;
           b_done     <= 1'b0;
          ph_ref3    <= 3'd0;
          c_done     <= 1'b0;
         lim        <= 3'd3;
