  // self-terminates one cycle after the data phase
  always @(posedge clk) begin
      if (rst)
          txph <= 2'b00;
      else if (step && !b_busy) begin
          if (tx_start)
              txph <= 2'b01;
          else
              txph <= {txph[0], 1'b0};
      end
  end

   always @(posedge clk) begin
       if (rst)
           bstate <= 3'b001;
       else if (step)
           bstate <= bnxt;
   end

   // beacon interval: reload on transmission, hold at zero until the air frees
   always @(posedge clk) begin
       if (rst)
           btimer <= 4'd15;
       else if (step) begin
           if (b_send)
               btimer <= 4'd15;
           else if (btimer != 4'd0)
