                            : (out_a != 4'd0 || rsv_a != 2'd0);
   wire       arb_idle = !gnt_a && !gnt_b && !p1_a && !p1_b &&
                         !p2_a && !p2_b && !p3_a && !p3_b && !p4_a && !p4_b;

   // a request is only latched while the shared shelf port is free
   wire accept = i_ce && arb_idle &&
                (i_take ? (used != CAP) : lane_nz);

   // commit of the move that has finished walking the shelf port
   wire take_fire = (p4_a || p4_b) &&  p4_take;
   wire give_fire = (p4_a || p4_b) && !p4_take;

