// Pseudo-random hall-call source.  The shift chain and its feedback XOR
// are split across two flops: the tap is evaluated one cycle ahead into
// lf_fb and shifted in on the next enabled step, which keeps the XOR
// gate out of the shift path.  Taps are chosen so that the combined
// 5-bit generator state {lf, lf_fb} is maximal length (period 31).
reg lf_fb;
// Quiet watchdog: reloaded on every hall call and decremented on every
// silent enabled step.  It is the budget of steps the generator may stay
// quiet before the cab is handed a target of its own.
reg [2:0] quiet_wd;
// Hall calls reach the cab through a one-deep request stage: the
// generator's decision and its floor are captured here and acted on
// the following enabled step, keeping the call decode off the
// pending-mask and watchdog paths.
reg       call_v;
reg [1:0] call_fl;

initial lf_fb   = 1'b0;
    initial lf      = 4'b0001;
    initial floor   = 2'd0;
    initial dir     = 1'b1;   // 1 = up, 0 = down
    initial pending = 4'b0000;
    initial dry_cnt = 3'd0;
    initial quiet_wd = 3'd3;
    initial call_v  = 1'b0;
    initial call_fl = 2'd0;

wire       lf_fb_next = lf[3] ^ lf[1];
wire [3:0] lf_next    = {lf[2:0], lf_fb};

// A pseudo-random hall call is issued unless the top three shift
// stages of the generator are all zero.
    wire       new_call   = (lf[3:1] != 3'b000);
    wire [1:0] call_floor = lf[1:0];

    wire at_top = (floor == 2'd3);
    wire at_bot = (floor == 2'd0);

    wire [1:0] floor_next = dir ? (at_top ? floor : floor + 2'd1)
                                : (at_bot ? floor : floor - 2'd1);
    wire       dir_next   = dir ? (at_top ? 1'b0 : 1'b1)
                                : (at_bot ? 1'b1 : 1'b0);

    // On the watchdog's last tick a call at the top floor is synthesized,
    // so a quiet generator cannot leave the cab without work.
    wire       wd_last    = (quiet_wd <= 3'd1);
    wire [3:0] set_mask   = call_v ? (4'b0001 << call_fl)
                                   : (wd_last ? 4'b1000 : 4'b0000);
    wire [3:0] clr_mask   = (4'b0001 << floor);

    always @(posedge clk) begin
        if (rst) begin
            lf      <= 4'b0001;
lf_fb   <= 1'b0;
            floor   <= 2'd0;
            dir     <= 1'b1;
            pending <= 4'b0000;
            dry_cnt <= 3'd0;
            quiet_wd <= 3'd3;
            call_v  <= 1'b0;
            call_fl <= 2'd0;
