            if (busy) begin
                if (!holding) begin
                   // winner released: drop the grant and start the bus turnaround
                    grant <= 4'b0000;
                    lock  <= 1'b0;
                   tail_cnt <= 2'd2;
                    hold_cnt <= 3'd0;
                   drn <= 1'b1;
