        phase = 2'd0;
        req   = 1'b0;
        ack   = 1'b0;
        busy  = 1'b0;
        occ   = 3'd0;
        armed = 1'b0;
        pv    = 1'b0;
occ_pend = 3'd0;
ce_ticks   = 4'd0;
ce_ticks_d = 4'd0;
    end

    always @(posedge clk)
        pv <= 1'b1;

always @(posedge clk) begin
    if (i_ce) begin
        ce_ticks_d <= ce_ticks;
        ce_ticks   <= ce_ticks + {3'd0, start} + 4'd1;
    end else begin
        ce_ticks   <= ce_ticks_d;
    end
end

