module boot_chunk_loader (
    input  wire i_clk,
    input  wire i_ce,      // idle when low: no state changes at all
    input  wire i_start,   // accept a fresh load request
    output wire o_expired,
    output wire o_done,
    output wire [7:0] o_total
);
    // A chunk loader that accumulates 3 bytes of payload per accepted step.
    // The accumulator is kept in two carry-save halves (acc_a, acc_b) whose
    // sum is the true byte total; `total` is the redundant true running sum.
localparam [3:0] TMAX  = 4'd9;   // countdown granted: 8 steps + 1 commit-stage cycle
    localparam [7:0] LIMIT = 8'd24;  // bytes that constitute completion
   localparam [3:0] TBMAX = 4'd6;   // channel B: shorter descriptor fetch

    reg [7:0] acc_a;
    reg [7:0] acc_b;
    reg [7:0] total;
    reg [3:0] timer;
   reg [3:0] timer_b;  // channel B countdown
   reg [3:0] aux;      // channel B byte accumulator
   reg       arb;      // round-robin priority for the shared commit register
reg       st_v;    // a step is sitting in the commit register
reg [3:0] st_lo;   // its low carry-save half-increment
reg [3:0] st_hi;   // its high carry-save half-increment
   reg       st_ch;   // which channel owns the in-flight step
    reg       pv;

    initial acc_a = 8'd0;
    initial acc_b = 8'd0;
    initial total = 8'd0;
    initial timer = TMAX;
   initial timer_b = TBMAX;
   initial aux = 4'd0;
   initial arb = 1'b0;
initial st_v  = 1'b0;
initial st_lo = 4'd0;
initial st_hi = 4'd0;
   initial st_ch = 1'b0;
    initial pv    = 1'b0;

    wire [7:0] csum    = acc_a + acc_b;   // halves recombined
    wire       expired = (timer == 4'd0);
   wire       req_a   = (timer   != 4'd0);
   wire       req_b   = (timer_b != 4'd0);
   wire       gnt_b   = req_b && (arb || !req_a);  // B takes the slot on its turn
   wire       gnt_a   = req_a && !gnt_b;

    assign o_expired = expired;
    assign o_done    = (csum >= LIMIT);
   assign o_total   = total + {4'd0, aux};   // bytes from both channels

    always @(posedge i_clk)
        pv <= 1'b1;

    always @(posedge i_clk) begin
        if (i_ce) begin
            if (i_start) begin
                acc_a <= 8'd0;
                acc_b <= 8'd0;
                total <= 8'd0;
                timer <= TMAX;
               timer_b <= TBMAX;
               aux   <= 4'd0;
               arb   <= 1'b0;
st_v  <= 1'b0;          // flush whatever was in flight
st_lo <= 4'd0;
st_hi <= 4'd0;
               st_ch <= 1'b0;
end else begin
   // stage 1: arbitrate the single commit register between the two channels
   if (gnt_a) begin
       st_v  <= 1'b1;
       st_ch <= 1'b0;
       st_lo <= 4'd1;
       st_hi <= 4'd2;
       timer <= timer - 4'd1;
       arb   <= 1'b1;
   end else if (gnt_b) begin
       st_v  <= 1'b1;
       st_ch <= 1'b1;
       st_lo <= 4'd1;
       st_hi <= 4'd0;          // B carries a single byte per step
       timer_b <= timer_b - 4'd1;
       arb   <= 1'b0;
   end else begin
       st_v  <= 1'b0;
       st_ch <= 1'b0;
       st_lo <= 4'd0;
       st_hi <= 4'd0;
   end
   // stage 2: commit the step issued last cycle to its own channel
   if (st_v && !st_ch) begin
       acc_a <= acc_a + {4'd0, st_lo};                  // low carry-save half
       acc_b <= acc_b + {4'd0, st_hi};                  // high carry-save half
       total <= total + {4'd0, st_lo} + {4'd0, st_hi};  // true total
   end else if (st_v && st_ch) begin
       aux   <= aux + st_lo;
   end
            end
        end
    end

    // Bounded response, safety form: the countdown must never expire while the
    // load request is still outstanding.  Edge form: the cycle `expired` rises,
    // the recombined accumulator must already show a completed transfer.
    always @(posedge i_clk)
        if (pv)
            assert (!$rose(expired) || (acc_a + acc_b >= LIMIT));
endmodule

