module npu_psum_lane (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,      // lane enable / idle when low
    input  wire        i_req,     // new accumulation request
    input  wire [7:0]  i_a,
    input  wire [7:0]  i_b,
    output reg  [19:0] o_psum,
    output reg         o_done
);
    // a full psum accumulation takes exactly MAX MAC steps
    localparam [3:0] MAX = 4'd12;

    // saturating up-counter: clamps at 12 although 4 bits admit 15
    reg [3:0] acc_cnt = 4'd0;
    // countdown that guarantees completion of an accepted request
    reg [4:0] ttl     = 5'd0;
    reg       busy    = 1'b0;
   // pipelined multiplier: the product of a MAC step is retimed through
   // four stages before it lands in the psum accumulator
   reg        mac_v1 = 1'b0;
   reg        mac_v2 = 1'b0;
   reg        mac_v3 = 1'b0;
   reg        mac_v4 = 1'b0;
   reg [15:0] mac_p1 = 16'd0;
   reg [15:0] mac_p2 = 16'd0;
   reg [15:0] mac_p3 = 16'd0;
   reg [15:0] mac_p4 = 16'd0;
   // one MAC step is issued per enabled busy cycle until the step count saturates
   wire       mac_issue = busy && (acc_cnt != MAX);

    initial o_psum = 20'd0;
    initial o_done = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            acc_cnt <= 4'd0;
            ttl     <= 5'd0;
            busy    <= 1'b0;
            o_psum  <= 20'd0;
            o_done  <= 1'b0;
           mac_v1  <= 1'b0;
           mac_v2  <= 1'b0;
           mac_v3  <= 1'b0;
           mac_v4  <= 1'b0;
           mac_p1  <= 16'd0;
           mac_p2  <= 16'd0;
           mac_p3  <= 16'd0;
           mac_p4  <= 16'd0;
        end else if (i_ce) begin
            o_done <= 1'b0;
           // MAC pipeline advances on every enabled cycle
           mac_p1 <= i_a * i_b;
           mac_v1 <= mac_issue;
           mac_p2 <= mac_p1;
           mac_v2 <= mac_v1;
           mac_p3 <= mac_p2;
           mac_v3 <= mac_v2;
           mac_p4 <= mac_p3;
           mac_v4 <= mac_v3;
           if (mac_v4) begin
               o_psum <= o_psum + mac_p4;
