        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
