        if (rst) begin
            pool <= TOTAL;
            hold <= 6'd0;
    gnt_q <= 6'd0;
gnt_p <= 6'd0;
used <= 4'd0;
ret <= 3'd0;
n_book <= 4'd0;
n_free <= 4'd0;
