    input  wire       i_ce,      // sample-enable; low => whole histogram idles
    input  wire [1:0] i_sel,     // which bin the incoming sample lands in
    output reg  [3:0] bin0,
    output reg  [3:0] bin1,
    output reg  [3:0] bin2,
    output reg  [3:0] bin3,
    output reg  [3:0] total,
output wire       o_full,
output reg  [3:0] ce_ticks,
output reg  [3:0] n_in,
output reg  [3:0] n_out,
output reg  [3:0] sel_trace
