// Packet-capture sensor credit window.
// TOTAL = 8 stream credits.  A burst send spends 3 credits (they become
// "outstanding" bytes in flight); the collector returns exactly one credit
// per enabled cycle while anything is outstanding.  A deadline register is
// reloaded on every accepted burst and counts down otherwise; it must never
// expire while credits are still outstanding.
module credit_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       i_send,    // producer requests a burst
output wire       o_busy,
output wire [3:0] o_nspend,  // ledger: credits handed to the link (wraps)
output wire [3:0] o_nret,    // ledger: credits taken back (wraps)
output wire       o_phase,   // which link slot the collector is in
output wire       o_rdy,     // collector has a return slot open
output wire [3:0] o_ngrant,  // ledger: return slots opened (wraps)
output wire [3:0] o_nuse     // ledger: return slots consumed (wraps)
);
    reg [3:0] avail;   // credits held by the sensor
    reg [3:0] outst;   // credits outstanding (in flight)
reg [3:0] stage;   // credits accepted for a burst but not yet on the link
reg [3:0] stage_b; // lane B stage buffer: second sensor stream, same link
reg       pri_b;   // round-robin owner of the next armed send slot
    reg [3:0] timer;   // completion deadline countdown
    reg       armed;   // sticky: set the first time a burst is accepted
reg [3:0] n_spend;  // event ledger: credits spent on bursts
reg [3:0] n_ret;    // event ledger: credits returned by the collector
reg       phase;    // half-rate return link: credits only come back on return slots
reg       rdy;      // a return slot is open and not yet used
reg [3:0] n_grant;  // event ledger: return slots opened by the collector
reg [3:0] n_use;    // event ledger: return slots consumed by a credit
reg       sready;   // framer has armed the link's send slot for a staged credit
reg [3:0] n_stg;    // event ledger: credits accepted into the stage buffer
reg [3:0] n_lnch;   // event ledger: staged credits launched onto the link
reg       req;      // burst request registered by the framer, debited next cycle
reg       ret_q;    // credit taken back by the collector, re-issued to the pool next cycle

    initial avail = 4'd8;
    initial outst = 4'd0;
initial stage = 4'd0;
    initial timer = 4'd0;
    initial armed = 1'b0;
initial n_spend = 4'd0;
initial n_ret = 4'd0;
initial phase = 1'b0;
initial rdy = 1'b0;
initial n_grant = 4'd0;
initial n_use = 4'd0;
initial sready = 1'b0;
initial n_stg = 4'd0;
initial n_lnch = 4'd0;
initial stage_b = 4'd0;
initial pri_b = 1'b0;
initial req = 1'b0;
initial ret_q = 1'b0;

wire send_ok = i_send && (avail >= 4'd3) && !req;   // accepted into the request register
wire commit  = req;                                 // the registered burst debits the ledger now
wire grant   = !phase && !rdy;                  // collector opens the next return slot
wire retire  = (outst != 4'd0) && phase && rdy;  // a credit comes back in an open slot
wire sopen   = phase && !sready;                 // framer arms the send slot during the return half
wire slot    = !phase && sready;                    // the armed send slot is live this cycle
wire push_a  = slot && (stage   != 4'd0) && (!pri_b || (stage_b == 4'd0));
wire push_b  = slot && (stage_b != 4'd0) && ( pri_b || (stage   == 4'd0));
wire push    = push_a || push_b;                    // exactly one lane takes the slot

assign o_busy = (outst != 4'd0) || (stage != 4'd0) || (stage_b != 4'd0) || req || ret_q;
assign o_nspend = n_spend;
assign o_nret   = n_ret;
assign o_phase  = phase;
assign o_rdy    = rdy;
assign o_ngrant = n_grant;
assign o_nuse   = n_use;

    always @(posedge clk) begin
        if (rst) begin
            avail <= 4'd8;
            outst <= 4'd0;
stage <= 4'd0;
stage_b <= 4'd0;
            timer <= 4'd0;
            armed <= 1'b0;
n_spend <= 4'd0;
n_ret <= 4'd0;
phase <= 1'b0;
rdy <= 1'b0;
n_grant <= 4'd0;
n_use <= 4'd0;
sready <= 1'b0;
n_stg <= 4'd0;
n_lnch <= 4'd0;
pri_b <= 1'b0;
req <= 1'b0;
ret_q <= 1'b0;
        end else if (i_ce) begin
phase <= ~phase;             // link alternates send / return slots
req   <= send_ok;            // request is registered one cycle before it spends
ret_q <= retire;             // returned credit waits a cycle in the re-issue register
if (commit) n_spend <= n_spend + 4'd3;
if (retire)  n_ret   <= n_ret   + 4'd1;
if (grant) begin
    rdy     <= 1'b1;         // slot opens during the send half-period
    n_grant <= n_grant + 4'd1;
end else if (retire) begin
    rdy   <= 1'b0;           // slot consumed by the returning credit
    n_use <= n_use + 4'd1;
end
if (sopen) sready <= 1'b1;        // send slot armed for the next send half-period
else if (push) sready <= 1'b0;    // slot consumed by the launched credit
if (commit) n_stg  <= n_stg  + 4'd2;
if (push)    n_lnch <= n_lnch + 4'd1;
if (push)    pri_b  <= ~pri_b;    // hand the next armed slot to the other lane
if (commit) begin
                // spend three credits, one may come back the same cycle
avail <= avail - 4'd3 + ret_q;
// one credit goes out on this slot, the other two wait one per lane
outst <= outst + 4'd1 + (push ? 4'd1 : 4'd0) - (retire ? 4'd1 : 4'd0);
stage   <= stage   + 4'd1 - (push_a ? 4'd1 : 4'd0);
stage_b <= stage_b + 4'd1 - (push_b ? 4'd1 : 4'd0);
timer <= 4'd15;         // deadline: half-rate return of up to 8 credits
                armed <= 1'b1;          // sticky arm
            end else if (retire) begin
avail <= avail + ret_q;   // the fresh return goes to ret_q, last cycle's lands now
                outst <= outst - 4'd1;
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end else begin
avail <= avail + ret_q;
if (push) begin
    outst <= outst + 4'd1;
if (push_a) stage   <= stage   - 4'd1;
if (push_b) stage_b <= stage_b - 4'd1;
end
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end
        end
    end

    // Bounded response (safety form), scoped after the first accepted burst:
    // the deadline never expires while credits are still outstanding.
    always @(*)
        assert (!armed || !((timer == 4'd0) && (outst != 4'd0)));
endmodule

