           p3_a <= 1'b0;
           p3_b <= 1'b0;
           p3_take <= 1'b0;
           p4_a <= 1'b0;
           p4_b <= 1'b0;
           p4_take <= 1'b0;
o_ce_beats <= 4'd0;
