           p1_b    <= gnt_b;
           p1_take <= gnt_take;
           p2_a    <= p1_a;
           p2_b    <= p1_b;
           p2_take <= p1_take;
           p3_a    <= p2_a;
           p3_b    <= p2_b;
           p3_take <= p2_take;
           p4_a    <= p3_a;
           p4_b    <= p3_b;
           p4_take <= p3_take;

           // stage 6: retire the move as it leaves the port
           out_a <= out_a_nxt;
           out_b <= out_b_nxt;
          rsv_a <= rsv_a_nxt;
         rsv_b <= rsv_b_nxt;
         used  <= out_a_nxt + rsv_a_nxt + out_b_nxt + rsv_b_nxt;   // running total over both lanes
