                          (p4_a && !p4_take && !a_drain) ? out_a - 4'd1 : out_a;
  // lane B fills its reserve before its counter and drains it first
  wire       b_fill  = p4_b &&  p4_take && (rsv_b != 2'd2);
  wire       b_drain = p4_b && !p4_take && (rsv_b != 2'd0);
  wire [1:0] rsv_b_nxt = b_fill  ? rsv_b + 2'd1 :
                         b_drain ? rsv_b - 2'd1 : rsv_b;
  wire [3:0] out_b_nxt = (p4_b &&  p4_take && !b_fill)  ? out_b + 4'd1 :
                         (p4_b && !p4_take && !b_drain) ? out_b - 4'd1 : out_b;

    always @(posedge clk) begin
        if (rst) begin
            used  <= 4'd0;
            avail <= CAP;
           out_a <= 4'd0;
           out_b <= 4'd0;
          rsv_a <= 2'd0;
         rsv_b <= 2'd0;
           turn  <= 1'b0;
           gnt_a <= 1'b0;
           gnt_b <= 1'b0;
           gnt_take <= 1'b0;
           p1_a <= 1'b0;
           p1_b <= 1'b0;
           p1_take <= 1'b0;
           p2_a <= 1'b0;
           p2_b <= 1'b0;
           p2_take <= 1'b0;
           p3_a <= 1'b0;
           p3_b <= 1'b0;
           p3_take <= 1'b0;
           p4_a <= 1'b0;
           p4_b <= 1'b0;
