module alu_result_fifo (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] a,
    input  wire [7:0] b,
    input  wire [1:0] op,
    output reg  [7:0] o_data,
    output reg        o_zero,
    output reg        o_carry,
    output wire       full,
    output wire       empty,
output reg  [3:0] count,
output wire [7:0] o_push_tally,
output reg  [3:0] o_op_shadow
);
    // ---- FIFO state: separate write/read pointers plus occupancy counter ----
    reg [2:0] wptr, rptr;
    reg [8:0] mem [0:7];   // {carry, result} slices
   // one-deep input staging register: the ALU result is captured here and
   // written into the array on the following enabled cycle
   reg        stg_v;
   reg  [8:0] stg_d;
  // second (skid) input slot: absorbs one more push while the staging slot
  // is still waiting for room in the array
  reg        skid_v;
  reg  [8:0] skid_d;
  // ---- push/pop transaction ledger ----
  // every accepted push logs one entry and every accepted pop logs one
  // retirement; both counts wrap freely at four bits.  The number of
  // entries the FIFO currently owns is the difference of the two logs,
  // which lets one 4-bit compare cover the array and both input slots.
  reg  [3:0] n_push, n_pop;
  assign o_push_tally = {n_pop, n_push};
    integer i;

    initial begin
        wptr    = 3'd0;
        rptr    = 3'd0;
        count   = 4'd0;
        o_data  = 8'h00;
        o_zero  = 1'b1;
        o_carry = 1'b0;
       stg_v   = 1'b0;
       stg_d   = 9'd0;
      skid_v  = 1'b0;
      skid_d  = 9'd0;
      n_push  = 4'd0;
      n_pop   = 4'd0;
o_op_shadow = 4'd0;
        for (i = 0; i < 8; i = i + 1) mem[i] = 9'd0;
    end

    // ---- 8-bit ALU slice: add, subtract, and, or (carry out in bit 8) ----
    wire [8:0] w_sum = {1'b0, a} + {1'b0, b};
    wire [8:0] w_dif = {1'b0, a} - {1'b0, b};
    reg  [8:0] alu;
    always @(*) begin
        case (op)
            2'b00:   alu = w_sum;
            2'b01:   alu = w_dif;
            2'b10:   alu = {1'b0, a & b};
            default: alu = {1'b0, a | b};
        endcase
    end

    // ---- full from the push/pop ledger, empty from the pointers ----
    wire [3:0] w_ledger = n_push - n_pop;
    assign full  = (w_ledger == 4'd5);
    assign empty = (wptr == rptr);

    wire do_push = i_ce && push && !full;
    wire do_pop  = i_ce && pop  && !empty;
   // the staging slot retires into the array whenever the array has room
   wire do_drain = i_ce && stg_v && ((wptr - rptr) != 3'd5);
  // the skid slot advances into the staging slot as soon as that slot frees up
  wire do_shift = i_ce && skid_v && (!stg_v || do_drain);

    always @(posedge clk) begin
       if (do_drain) begin
           mem[wptr] <= stg_d;
           wptr      <= wptr + 3'd1;
       end
      if (do_shift) begin
          stg_d <= skid_d;
          stg_v <= 1'b1;
      end else if (do_drain) begin
          stg_v <= 1'b0;
      end
       if (do_push) begin
          skid_d <= alu;
          skid_v <= 1'b1;
      end else if (do_shift) begin
          skid_v <= 1'b0;
       end
        if (do_pop) begin
            o_data  <= mem[rptr][7:0];
            o_carry <= mem[rptr][8];
            o_zero  <= (mem[rptr][7:0] == 8'h00);
            rptr    <= rptr + 3'd1;
        end
        if (do_push && !do_pop)
            count <= count + 4'd1;
        else if (!do_push && do_pop)
            count <= count - 4'd1;
        else
            count <= count;
        if (do_push)
            n_push <= n_push + 4'd1;
        if (do_pop)
            n_pop  <= n_pop  + 4'd1;
if (i_ce)
    o_op_shadow <= {o_op_shadow[2:0], (^op) ^ a[0] ^ b[0]};
    end

    // P: occupancy never exceeds the depth of 5, though the register holds 15
    always @(*) assert (count <= 4'd5);
endmodule

