    initial len = 3'd0;
    initial esc_ret = S_IDLE;
   initial st_s  = S_IDLE;
   initial len_s = 3'd0;
   initial s_vld = 1'b0;
   initial st_b  = S_IDLE;
   initial len_b = 3'd0;
   initial esc_b = S_IDLE;
   initial own   = 1'b0;
