  // self-terminates one cycle after the data phase
  always @(posedge clk) begin
      if (rst)
          txph <= 2'b00;
      else if (step && !b_busy) begin
          if (tx_start)
              txph <= 2'b01;
          else
              txph <= {txph[0], 1'b0};
      end
  end

   always @(posedge clk) begin
      if (rst) begin
          bstate <= 3'b001;
          pa_arm0 <= 1'b0;
          pa_arm1 <= 1'b0;
          pa_arm2 <= 1'b0;
          pa_arm3 <= 1'b0;
      end
       else if (step)
      begin
          bstate <= bnxt;
          // bias settle: one stage per cycle, a single token in flight
          pa_arm0 <= b_arm;
          pa_arm1 <= pa_arm0;
          pa_arm2 <= pa_arm1;
          pa_arm3 <= pa_arm2;
      end
