                end
           end else if (tail_cnt != 2'd0) begin
              // turnaround: dead beats before the drain slot may empty
               tail_cnt <= tail_cnt - 2'd1;
              if (tail_cnt == 2'd1) begin
                  // last dead beat: the credit moves into the park slot
                  occ  <= occ - 3'd1;
                  park <= 1'b1;
