                  lock  <= 1'b1;
                  hold_cnt <= 3'd0;
                  occ  <= occ + 3'd1;
                  park <= 1'b0;
                  drn  <= 1'b0;
              end else begin
                  // credit-return beat: the parked credit goes back to the pool
                  drn  <= 1'b0;
                  park <= 1'b0;
              end
